    const d=this._date(value); if(!d) return value&&value!=='unknown'&&value!=='unavailable'?String(value):'–';
    return new Intl.DateTimeFormat('nb-NO',{dateStyle:'short',timeStyle:'medium',timeZone:'Europe/Oslo'}).format(d);
