    const defs=[['database','sensor.gjaeringsassistent_systemkontroll_database'],['schema','sensor.gjaeringsassistent_systemkontroll_skjema'],['writable','sensor.gjaeringsassistent_systemkontroll_skrivbarhet'],['home_assistant','sensor.gjaeringsassistent_systemkontroll_home_assistant'],['session','sensor.gjaeringsassistent_systemkontroll_sesjon'],['frontend_publishing','sensor.gjaeringsassistent_systemkontroll_frontendpublisering'],['node_red','sensor.gjaeringsassistent_systemkontroll_node_red'],['measurement_source','sensor.gjaeringsassistent_malekilde'],['runtime','sensor.gjaeringsassistent_systemkontroll_runtimefil'],['configuration','sensor.gjaeringsassistent_systemkontroll_konfigurasjon'],['time','sensor.gjaeringsassistent_systemkontroll_tid']];
    return defs.map(([id,entity])=>{const a=this._attrs(entity),raw=this._state(entity);return {check_id:a.check_id||id,status:a.status||raw.split(' · ')[0].toLowerCase(),severity:a.severity||null,summary:a.summary||raw.split(' · ').slice(1).join(' · ')};});
