    const out=[]; for(const id of ['sensor.gjaeringsassistent_driftsmelding_1','sensor.gjaeringsassistent_driftsmelding_2','sensor.gjaeringsassistent_driftsmelding_3','sensor.gjaeringsassistent_driftsmelding_4','sensor.gjaeringsassistent_driftsmelding_5']){const e=this._attrs(id).event;if(e)out.push(e);} return out;
