  async _runSystemCheck(button){ if(!this._hass)return;const entity=this._config.systemcheck_entity||'button.gjaeringsassistent_kjor_systemkontroll',statusEntity='sensor.gjaeringsassistent_systemkontroll_sist_kjort',before=this._state(statusEntity);button.disabled=true;this._systemCheckStatus='Starter systemkontroll …';this._renderSystem();try{await this._hass.callService('button','press',{entity_id:entity});const done=await this._waitFor(()=>{const now=this._state(statusEntity);return now&&now!==before&&now!=='unknown'&&now!=='unavailable'?now:null;});this._systemCheckStatus=done?`Systemkontroll fullført · ${this._time(done)}`:'Systemkontroll mottatt, men ingen ny DB-kvittering innen 5 sekunder.';}catch(error){this._systemCheckStatus=`Systemkontroll feilet: ${error?.message||error}`;}finally{this._renderSystem();} }
  _localFileStamp(d=new Date()){ const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(d).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return `${p.year}${p.month}${p.day}T${p.hour}${p.minute}${p.second}`; }
  _technicalFilename(){const now=new Date();return `${this._localFileStamp(now)}${String(now.getMilliseconds()).padStart(3,'0')}-gjaeringsassistent-teknisk-status.json`;}
