  _templateField(label,path,value,readonly=false,type='text'){ const disabled=readonly?'disabled':'';const checked=type==='checkbox'&&value?'checked':'';const val=type==='checkbox'?'':`value="${this._esc(value??'')}"`;return `<label class="template-field"><span>${this._esc(label)}</span><input class="template-input" data-path="${this._esc(path)}" data-kind="${type==='number'?'number':type==='checkbox'?'boolean':'string'}" type="${type}" ${type==='number'?'step="any" ':''}${disabled} ${checked} ${val}></label>`; }
