    this.shadowRoot.innerHTML=`<style>${this._templateStyles()}.library{display:grid;gap:10px}.library-filter{display:flex;gap:6px;align-items:center}.library-filter select{padding:6px;border:1px solid var(--divider-color);border-radius:6px;background:var(--card-background-color);color:var(--primary-text-color)}.selected-row{background:color-mix(in srgb,var(--primary-color) 9%,transparent)}.status-published{background:color-mix(in srgb,#2e7d32 18%,var(--card-background-color))}.status-draft{background:color-mix(in srgb,#1976d2 16%,var(--card-background-color))}.status-retired{background:color-mix(in srgb,#757575 18%,var(--card-background-color))}.new-template,.comparison,.selected-template{border:1px solid var(--divider-color);border-radius:11px;padding:10px}.new-template summary,.comparison summary{font-weight:700;cursor:pointer;margin-bottom:8px}.new-template-row{grid-template-columns:2fr 1fr 2fr auto}</style><ha-card><div class="wrap"><div class="top"><div><h2>${this._esc(this._config.title||'Template')}</h2><small>Templateadministrasjon og editor · uavhengig av Start/runtime</small></div><div class="top"><span class="badge">${this._esc(this._templateModeLabel(mode))}</span><button class="secondary refresh-template">Oppdater</button></div></div>${this._templateStatus?`<div class="status">${this._esc(this._templateStatus)}</div>`:''}${active}${library}${selected}</div></ha-card>`;
    this.shadowRoot.querySelector('.refresh-template')?.addEventListener('click',()=>this._refreshTemplateBackend());
    this.shadowRoot.querySelector('.template-filter')?.addEventListener('change',e=>{this._templateFilter=e.currentTarget.value;this._renderTemplate();});
    this.shadowRoot.querySelectorAll('.library-open').forEach(b=>b.addEventListener('click',()=>this._templateCall('gjaeringsassistent_template_admin_select',{version_id:b.dataset.version},'Åpner templateversjon …')));
    this.shadowRoot.querySelector('.create-template')?.addEventListener('click',()=>{const source=this.shadowRoot.querySelector('.new-template-source')?.value||'',id=this.shadowRoot.querySelector('.new-template-id')?.value?.trim()||'',name=this.shadowRoot.querySelector('.new-template-name')?.value?.trim()||'';if(!source||!/^[A-Za-z0-9._-]{1,128}$/.test(id)||!name){this._templateStatus='Ny template krever kildeversjon, gyldig template-ID og navn.';this._renderTemplate();return;}this._templateCall('gjaeringsassistent_template_draft_clone',{source_version_id:source,new_template_id:id,new_name:name},'Oppretter ny template-draft …');});
    this.shadowRoot.querySelectorAll('details[data-detail-key]').forEach(d=>d.addEventListener('toggle',()=>{const k=d.dataset.detailKey;if(!k)return;d.open?this._templateOpenDetails.add(k):this._templateOpenDetails.delete(k);}));
    if(['published','retired'].includes(mode))this.shadowRoot.querySelector('.clone-draft')?.addEventListener('click',()=>this._templateCall('gjaeringsassistent_template_draft_clone',{source_version_id:data.selected_version_id},'Oppretter / åpner draft …'));
    this.shadowRoot.querySelector('.retire-template')?.addEventListener('click',()=>{if(!window.confirm('Sette denne publiserte versjonen som utgått? Den forsvinner fra Start, men historiske/frosne sessioner påvirkes ikke.'))return;this._templateCall('gjaeringsassistent_template_lifecycle',{version_id:data.selected_version_id,action:'retire'},'Setter versjonen utgått …');});
    this.shadowRoot.querySelector('.reactivate-template')?.addEventListener('click',()=>this._templateCall('gjaeringsassistent_template_lifecycle',{version_id:data.selected_version_id,action:'reactivate'},'Aktiverer versjonen igjen …'));
    for(const [selector,key] of [['.new-template-id','newTemplateId'],['.new-template-name','newTemplateName'],['.new-template-source','newTemplateSource'],['.publish-label','publishLabel']]){const el=this.shadowRoot.querySelector(selector);if(!el)continue;const retain=e=>{this._templateFormDraft[key]=e.currentTarget.value;this._templateEditRevision++;};el.addEventListener('input',retain);el.addEventListener('change',retain);}
