  _nearestSeriesAt(value){const target=this._date(value)?.getTime();if(!Number.isFinite(target))return null;let best=null;for(const row of this._overviewData?.series||[]){const at=this._date(row.at)?.getTime();if(!Number.isFinite(at))continue;const delta=Math.abs(at-target);if(!best||delta<best.delta)best={row,delta};}return best&&best.delta<=30*60000?best.row:null;}
