// BEGIN SQLITE ARCHIVE UI
// Transport and presentation only. Selections persist across read-model refresh.
function gaArchiveSha256(bytes){
 const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
 const H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19],W=new Uint32Array(64),rotr=(x,n)=>(x>>>n)|(x<<(32-n));
 const length=Math.ceil((bytes.length+9)/64)*64;
 const byte=i=>i<bytes.length?bytes[i]:i===bytes.length?128:i>=length-8?Number((BigInt(bytes.length)*8n>>BigInt((length-1-i)*8))&255n):0;
 for(let off=0;off<length;off+=64){
  for(let i=0;i<16;i++)W[i]=(byte(off+i*4)<<24)|(byte(off+i*4+1)<<16)|(byte(off+i*4+2)<<8)|byte(off+i*4+3);
  for(let i=16;i<64;i++){const a=W[i-15],b=W[i-2];W[i]=(W[i-16]+(rotr(a,7)^rotr(a,18)^(a>>>3))+W[i-7]+(rotr(b,17)^rotr(b,19)^(b>>>10)))>>>0;}
  let [a,b,c,d,e,f,g,h]=H;
  for(let i=0;i<64;i++){const t1=(h+(rotr(e,6)^rotr(e,11)^rotr(e,25))+((e&f)^(~e&g))+K[i]+W[i])>>>0,t2=((rotr(a,2)^rotr(a,13)^rotr(a,22))+((a&b)^(a&c)^(b&c)))>>>0;h=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}
  [a,b,c,d,e,f,g,h].forEach((v,i)=>H[i]=(H[i]+v)>>>0);
 }
 return H.map(v=>v.toString(16).padStart(8,'0')).join('');
}
class GjaeringsassistentArchiveCard extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this._files=[];this._operation=null;this._selectedCandidate='';this._mode='template';this._busy=false;}
 setConfig(config){this._config=config;}
 set hass(hass){this._hass=hass;if(!this._timer&&this.isConnected){this._refresh();this._timer=setInterval(()=>this._refresh(),3000);}}
 connectedCallback(){if(this._hass&&!this._timer){this._refresh();this._timer=setInterval(()=>this._refresh(),3000);}}
 disconnectedCallback(){clearInterval(this._timer);this._timer=null;}
 getCardSize(){return 10;}
 _esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 _id(){return 'archive-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)).replaceAll('-','');}
 async _call(action,data={}){const operation_id=data.operation_id||this._id();await this._hass.callApi('POST','events/gjaeringsassistent_archive',{action,operation_id,...data});return operation_id;}
 async _refresh(){try{const response=await fetch((this._config?.data_url||'/local/gjaeringsassistent/archive-library.json')+'?v='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('Arkivbibliotek venter på oppdatering');this._data=await response.json();const last=(this._data.transfers||[]).find(t=>t.operation_id===this._operation);if(last&&last.status!=='busy'&&last.event_seq!==this._lastEventSeq){this._status=null;this._lastEventSeq=last.event_seq;}if(!this._busy)this._render();}catch(e){if(!this._busy){this._status=e.message;this._render();}}}
 async _wait(test,timeout=60000){const start=Date.now();while(Date.now()-start<timeout){await this._refresh();if(test())return;await new Promise(resolve=>setTimeout(resolve,500));}throw Error('Ingen fullføringskvittering ennå. Oppdater biblioteket og kontroller status.');}
 _statusText(text){this._status=text;const el=this.shadowRoot.querySelector('.transfer-status');if(el)el.textContent=text;}
 async _upload(file){
  if(!file||!file.name.toLowerCase().endsWith('.sqlite')||file.size<1||file.size>536870912)throw Error('Velg et SQLite-arkiv på opptil 512 MiB');
  const bytes=new Uint8Array(await file.arrayBuffer()),upload_id=this._id(),chunks=Math.ceil(bytes.length/65536);
  const sha256=globalThis.crypto?.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join(''):gaArchiveSha256(bytes);
  await this._call('upload_begin',{upload_id,filename:file.name,bytes:bytes.length,chunks,sha256});await this._wait(()=>this._data?.uploads?.some(u=>u.upload_id===upload_id));
  for(let i=0;i<chunks;i++){const slice=bytes.subarray(i*65536,(i+1)*65536);let binary='';for(let j=0;j<slice.length;j+=8192)binary+=String.fromCharCode(...slice.subarray(j,j+8192));await this._call('upload_chunk',{upload_id,chunk_no:i,payload:btoa(binary)});this._statusText(`Laster opp ${file.name} · ${Math.round((i+1)*100/chunks)} %`);if((i+1)%12===0)await this._wait(()=>this._data?.uploads?.some(u=>u.upload_id===upload_id&&Number(u.received_chunks)>=i+1));}
  await this._wait(()=>this._data?.uploads?.some(u=>u.upload_id===upload_id&&Number(u.received_chunks)===chunks&&Number(u.received_bytes)===bytes.length));return upload_id;
 }
 async _preview(){if(this._busy)return;this._busy=true;try{
  this._statusText('Leser og laster opp arkivfiler …');const upload_ids=[],checksum_files=[];
  for(const file of this._files){if(file.name.toLowerCase().endsWith('.sqlite'))upload_ids.push(await this._upload(file));else if(/\.sha(?:256)?$/i.test(file.name)){checksum_files.push({filename:file.name,text:file.size<=8192?await file.text():''});}}
  if(!upload_ids.length)throw Error('Velg template.sqlite og eventuelt gjæring.sqlite med SHA-filene');
  this._operation=await this._call('inspect_files',{upload_ids,checksum_files});this._inspectOperation=this._operation;this._selectedCandidate='';this._mode='template';this._submitted=false;this._status='Arkivfiler lastet opp · venter på kontroll';
 }catch(e){this._status=e.message;}finally{this._busy=false;await this._refresh();}}
 async _action(action,data={}){try{this._operation=await this._call(action,data);this._status=null;this._render();}catch(e){this._status=e.message;this._render();}}
 _links(row){return [['archive_url','Gjæring.sqlite'],['archive_sha_url','Gjæring.sha'],['template_url','Template.sqlite'],['template_sha_url','Template.sha'],['report_url','Rapport.html']].filter(([key])=>row[key]).map(([key,label])=>`<a target="_blank" rel="noopener" href="${this._esc(row[key])}" download>${label}</a>`).join(' · ');}
 _render(){
  const opened=Array.from(this.shadowRoot.querySelectorAll('details')).map(e=>e.open),data=this._data||{},last=(data.transfers||[]).find(t=>t.operation_id===this._operation),esc=v=>this._esc(v);
  const candidates=(data.candidates||[]).filter(c=>c.operation_id===this._inspectOperation);
  if(!this._selectedCandidate&&candidates.length)this._selectedCandidate=candidates[0].candidate_id;
  const candidate=candidates.find(c=>c.candidate_id===this._selectedCandidate),warnings=(data.checksum_warnings||[]).filter(w=>candidate&&w.operation_id===candidate.operation_id&&[candidate.template_upload_id,candidate.session_upload_id].includes(w.upload_id));
  const sessions=(data.sessions||[]).map(s=>`<tr><td><b>${esc(s.batch_name)}</b><br><small>${esc(s.archive_origin_display)} · ${esc(s.snapshot_display)} · ${esc(s.original_session_id||s.session_id)}</small></td><td>${esc(s.pitched_at)}</td><td><button data-export-session="${esc(s.session_id)}">Eksporter SQLite og rapport</button> ${this._links(s)}</td><td><button data-visibility="${esc(s.session_id)}" data-visible="${Number(s.comparison_visible)===1?0:1}">${Number(s.comparison_visible)===1?'Skjul fra sammenligning':'Vis i sammenligning'}</button>${Number(s.can_delete)===1?`<button data-delete-session="${esc(s.session_id)}">Slett gjæring fra MariaDB</button>${Number(s.can_delete_template)===1?`<label><input type="checkbox" data-delete-related="${esc(s.session_id)}"> Slett også ubrukt importert template</label>`:''}`:''}</td></tr>`).join('');
  const templates=['system','own','imported'].map(kind=>{const rows=(data.templates||[]).filter(t=>t.origin_kind===kind).map(t=>`<tr><td>${esc(t.name)} · ${esc(t.version_label)}<br><small>${esc(t.template_id)}${t.original_template_id?' · kilde '+esc(t.original_template_id):''}</small></td><td><button data-export-template="${esc(t.version_id)}">Eksporter template og SHA</button>${kind==='imported'?Number(t.can_delete)===1?`<button data-delete-template="${esc(t.template_id)}">Slett importert template</button>`:`<small>Brukes av ${esc(t.session_references)} sesjoner og ${esc(t.derived_references)} egne templates.</small>`:''}</td></tr>`).join('');return `<h3>${esc(({system:'Systemtemplates',own:'Egne templates',imported:'Importerte originaler'})[kind])}</h3><table><tbody>${rows||'<tr><td>Ingen templates i denne kategorien.</td></tr>'}</tbody></table>`;}).join('');
  const active=(data.active||[]).map(s=>`<p><b>${esc(s.batch_name)}</b> · Aktiv gjæring <button data-export-session="${esc(s.session_id)}">Eksporter aktivt øyeblikksbilde</button><br><small>Gjæring.sqlite, template.sqlite, to SHA-filer og HTML-rapport. Gjæringen fortsetter.</small></p>`).join('');
  this.shadowRoot.innerHTML=`<style>:host{display:block}.wrap{padding:18px;display:grid;gap:12px}h2,h3{margin:4px 0}table{width:100%;border-collapse:collapse}td{border-bottom:1px solid var(--divider-color);padding:10px;vertical-align:top}button,select{margin:4px;padding:7px}button{cursor:pointer}small{color:var(--secondary-text-color)}a{color:var(--primary-color)}.scroll{overflow:auto}.transfer-status{padding:10px;background:var(--secondary-background-color)}label{display:block;margin:8px 0}.error{color:var(--error-color)}.warning{padding:10px;border-left:4px solid var(--warning-color,#e9a028)}</style><ha-card><div class="wrap"><h2>Gjæringsarkiv og template-arkiv</h2><div class="transfer-status">${esc(this._status||last?.message||'Klar')} ${last?this._links(last):''}</div>${active}<details><summary>Importer SQLite-arkiv</summary><p>Velg arkivfilene og SHA-filene samlet. Velg deretter template-navn og hva som skal importeres.</p><input type="file" accept=".sqlite,.sha,.sha256" multiple class="archive-files"><small>${esc(this._files.map(f=>f.name).join(' · ')||'Ingen filer valgt')}</small><button class="preview" ${this._busy?'disabled':''}>Les arkivfiler</button>${candidates.length?`<label>Arkiv <select class="candidate">${candidates.map(c=>`<option value="${esc(c.candidate_id)}" ${c.candidate_id===this._selectedCandidate?'selected':''}>${esc(c.display_name)}</option>`).join('')}</select></label>`:''}${candidate?`<p>${esc(candidate.measurement_count)} målepunkter · pitch ${esc(candidate.pitched_at||'–')}</p>${warnings.map(w=>`<div class="warning">${esc(w.message)}</div>`).join('')}<label><input type="radio" name="import-mode" value="template" ${this._mode==='template'?'checked':''}> Kun template, som ny importert original</label><label><input type="radio" name="import-mode" value="session" ${this._mode==='session'?'checked':''} ${Number(candidate.can_import_session)===1?'':'disabled'}> Template og gjæringsdata</label>${Number(candidate.can_import_session)!==1?'<small>Gjæringsimport krever SQLite-filen fra samme eksportsett.</small>':''}<button class="import-confirm" ${this._submitted?'disabled':''}>${this._mode==='session'?'Importer gjæring og template':'Importer bare template'}</button>`:''}</details><h3>Gjæringer</h3><div class="scroll"><table><tbody>${sessions||'<tr><td>Ingen historiske gjæringer.</td></tr>'}</tbody></table></div><details><summary>Templates etter kategori</summary>${templates}</details><details><summary>Siste arkivoperasjoner</summary>${(data.transfers||[]).map(t=>`<p>${esc(t.message)} · ${esc(t.occurred_at)} ${this._links(t)}</p>`).join('')}</details></div></ha-card>`;
  this.shadowRoot.querySelectorAll('details').forEach((e,i)=>{e.open=Boolean(opened[i]);});
  this.shadowRoot.querySelector('.archive-files')?.addEventListener('change',e=>{this._files=Array.from(e.target.files);this._inspectOperation=null;this._operation=null;this._status=null;this._selectedCandidate='';this._render();});
  this.shadowRoot.querySelector('.preview')?.addEventListener('click',()=>this._preview());
  this.shadowRoot.querySelector('.candidate')?.addEventListener('change',e=>{this._selectedCandidate=e.target.value;this._submitted=false;this._mode='template';this._render();});
  this.shadowRoot.querySelectorAll('[name="import-mode"]').forEach(e=>e.addEventListener('change',()=>{this._mode=e.value;this._render();}));
  this.shadowRoot.querySelector('.import-confirm')?.addEventListener('click',()=>{if(this._submitted||!candidate)return;this._submitted=true;this._action(this._mode==='session'?'import_session':'import_template',{candidate_id:candidate.candidate_id});});
  this.shadowRoot.querySelectorAll('[data-export-session]').forEach(e=>e.addEventListener('click',()=>this._action('export_session',{session_id:e.dataset.exportSession})));
  this.shadowRoot.querySelectorAll('[data-export-template]').forEach(e=>e.addEventListener('click',()=>this._action('export_template',{version_id:e.dataset.exportTemplate})));
  this.shadowRoot.querySelectorAll('[data-visibility]').forEach(e=>e.addEventListener('click',()=>this._action('visibility',{session_id:e.dataset.visibility,visible:Number(e.dataset.visible)})));
  this.shadowRoot.querySelectorAll('[data-delete-session]').forEach(e=>e.addEventListener('click',()=>{const id=e.dataset.deleteSession,row=(data.sessions||[]).find(s=>s.session_id===id),related=this.shadowRoot.querySelector(`[data-delete-related="${id}"]`)?.checked||false;if(window.confirm(`Slett «${row?.batch_name||id}» og alle tilhørende målinger og hendelser fra MariaDB${related?', samt den importerte templaten':''}? Eksportfiler beholdes.`))this._action('delete_session',{session_id:id,delete_template:related});}));
  this.shadowRoot.querySelectorAll('[data-delete-template]').forEach(e=>e.addEventListener('click',()=>{const id=e.dataset.deleteTemplate,row=(data.templates||[]).find(t=>t.template_id===id);if(window.confirm(`Slett importert template «${row?.name||id}» fra MariaDB? Eksportfiler beholdes.`))this._action('delete_template',{template_id:id});}));
 }
}
